              resp->safety_status.status = ur_dashboard_msgs::msg::SafetyStatus::PROFISAFE_WAITING_FOR_PARAMETERS;
            } else if (safety_status_str == "PROFISAFE_AUTOMATIC_MODE_SAFEGUARD_STOP") {
              resp->safety_status.status =
